63	                logger.debug("cancel-tasks rejected task [{}]; reporting as reindex not found", taskId);
64	                l.onFailure(ReindexCancellation.notFoundException(taskId));
65	                return;
66	            }
67	            // Surface other failures as-is
68	            final Exception cancelFailure = ReindexCancellation.cancellationFailure(cancelResponse);
69	            if (cancelFailure != null) {
70	                l.onFailure(cancelFailure);
71	                return;
72	            }
73	            // No failure was reported but no task was matched either
74	            if (cancelResponse.getTasks().isEmpty()) {
75	                l.onFailure(ReindexCancellation.notFoundException(taskId));
76	                return;
77	            }
78	
79	            if (request.waitForCompletion()) {
80	                // Fetch the completed reindex result with relocation following so the response reflects the original task identity.
81	                final GetReindexRequest getRequest = new GetReindexRequest(taskId, true, null);
82	                client.execute(
83	                    TransportGetReindexAction.TYPE,
84	                    getRequest,
85	                    l.delegateFailureAndWrap(
86	                        (l2, getResp) -> l2.onResponse(ReindexCancellation.completedResponse(getResp))
87	                    )
88	                );
89	            } else {
90	                l.onResponse(new CancelReindexResponse((GetReindexResponse) null));
91	            }
92	        }));
93	    }
94	}

